 static final Path OUT=Path.of(System.getProperty("kelmagic.qaOutput","qa-r11"));static boolean opened,requested,configured;static volatile boolean ready,groveDone;static int wait,settle,frame,stage=-1,checks;static final BlockPos TREE=new BlockPos(180,-60,-8),BED=new BlockPos(205,-60,0),FIELD=new BlockPos(205,-61,10),GROVE=new BlockPos(260,-60,80);
