 static ThresholdPortal endpoint(ServerPlayer p){var d=ThresholdLinks.get(p.server);var e=d.ends.values().stream().filter(t->t.owner().equals(p.getUUID())&&t.mate()==null).findFirst().orElseThrow();return (ThresholdPortal)p.server.getLevel(e.dimension()).getEntity(e.id());}
