  var trial=new BlockPos(160,-60,40);for(boolean natural:List.of(false,true)){clear(l,trial,13,34);var feature=natural?MagicDreams.NATURAL_TREE.get():MagicDreams.TREE.get();ok(feature.place(new net.minecraft.world.level.levelgen.feature.FeaturePlaceContext<>(Optional.empty(),l,l.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(51),trial,net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration.INSTANCE)),"tree grows natural="+natural);for(int y=0;y<18;y++)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)ok(l.getBlockState(trial.offset(x,y,z)).is(MagicGrove.LOG.get()),"3x3 trunk "+natural);for(var d:Direction.Plane.HORIZONTAL)for(int y=0;y<2;y++)ok(l.getBlockState(trial.relative(d,2).above(y)).is(MagicGrove.LOG.get()),"two-high centred root "+d);int leaf=0,gold=0;for(var q:BlockPos.betweenClosed(trial.offset(-12,0,-12),trial.offset(12,34,12))){var s=l.getBlockState(q);if(s.getBlock() instanceof LeavesBlock){leaf++;if(s.is(MagicGrove.NATURAL_GOLDEN_LEAVES.get())||s.is(MagicGrove.GOLDEN_LEAVES.get()))gold++;ok(s.getValue(LeavesBlock.DISTANCE)<=6,"supported leaf");}}ok(leaf>250,"open crown has foliage");if(natural)ok(gold/(double)leaf>.11&&gold/(double)leaf<.19,"natural golden foliage about 15 percent: "+gold+"/"+leaf);}
  clear(l,trial,13,34);put(l,trial.above(6),Blocks.DIAMOND_BLOCK.defaultBlockState());ok(!MagicDreams.TREE.get().place(new net.minecraft.world.level.levelgen.feature.FeaturePlaceContext<>(Optional.empty(),l,l.getChunkSource().getGenerator(),l.random,trial,net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration.INSTANCE)),"tree preflight blocks building");ok(l.getBlockState(trial).isAir(),"no partial trunk");clear(l,trial,13,34);
